package com.bte.service;
import com.bte.dto.*;import com.bte.entity.*;import com.bte.enums.*;import com.bte.exception.*;import java.util.*;import java.math.BigDecimal;
public final class PayoutDeclarationRules {
 private PayoutDeclarationRules(){}
 public static void validate(Tournament t,List<Registration> entries,List<MatchResult> matches,EscrowSettlementRequest request){
  var paid=entries.stream().filter(r->r.getPaymentStatus()==PaymentStatus.PAID).toList();int count=Math.min(3,paid.size());if(count==0 || request.winners()==null || request.winners().size()!=count)throw new BadRequestException("Declare the top "+count+" funded teams");
  if(t.getStatus()==TournamentStatus.UPCOMING || t.getStatus()==TournamentStatus.CANCELLED || t.getStatus()==TournamentStatus.COMPLETED || matches.isEmpty() || (t.getPlannedRounds()>0 && matches.size()!=t.getPlannedRounds()))throw new BadRequestException("All tournament matches must finish before winner declaration");
  var ranks=new HashMap<Long,Integer>();if(t.getPlannedRounds()>0){for(var row:TournamentStandingsService.aggregate(matches,paid))ranks.put(row.captainUserId(),row.rank());}else for(var row:matches.getLast().getRankings()){Long id=paid.stream().filter(r->Objects.equals(row.getPlayerUserId(),r.getGuestAccountId())).map(Registration::getOwnerUserId).findFirst().orElse(row.getPlayerUserId());ranks.put(id,row.getRank());}
  var seen=new HashSet<Long>();var positions=new HashSet<Integer>();BigDecimal sum=BigDecimal.ZERO;for(var winner:request.winners()){if(winner==null || winner.userId()==null || winner.rank()==null || winner.winnersPoolPercent()==null || winner.rank()<1 || winner.rank()>count || winner.winnersPoolPercent().signum()<=0 || winner.winnersPoolPercent().compareTo(new BigDecimal("100"))>0 || !seen.add(winner.userId()) || !positions.add(winner.rank()) || !winner.rank().equals(ranks.get(winner.userId())) || paid.stream().noneMatch(r->Objects.equals(winner.userId(),r.getOwnerUserId())))throw new BadRequestException("Declare unique paid captains in their published top-3 ranking positions");sum=sum.add(winner.winnersPoolPercent());}if(sum.compareTo(new BigDecimal("100"))!=0)throw new BadRequestException("Winner shares must total 100% of the winners pool");
 }
 public static boolean sameWinners(EscrowSettlementRequest left,EscrowSettlementRequest right){if(left.winners()==null || right.winners()==null)return false;return left.winners().stream().map(w->w.userId()+":"+w.rank()+":"+w.winnersPoolPercent().stripTrailingZeros().toPlainString()).sorted().toList().equals(right.winners().stream().map(w->w.userId()+":"+w.rank()+":"+w.winnersPoolPercent().stripTrailingZeros().toPlainString()).sorted().toList());}
}
